const body = ($json.body && $json.body) || $json;
const prompt = (body.prompt !== undefined && body.prompt !== null) ? String(body.prompt).trim() : '';
const type = (body.type !== undefined && body.type !== null && String(body.type).trim() !== '') ? String(body.type).trim() : 'flux-pro/kontext/text-to-image';
let count = (body.count !== undefined && body.count !== null && body.count !== '') ? Number(body.count) : 1;
if (!Number.isFinite(count) || count < 1) count = 1;
count = Math.min(4, Math.floor(count));
if (prompt === '') {
  return [{ json: { ok: false, error: 'prompt обязателен' } }];
}
return [{ json: { ok: true, payload: { model_name: type, input_params: { prompt: prompt, num_images: count } } } }];

// HTTP Request не прокидывает входной item: $json здесь = ответ credits API.
// Валидацию и payload берём кросс-нод-ссылкой на Code validate.
const v = $('Code validate').first().json;
if (v.ok === false) { return [{ json: v }]; }
// Универсальный парсер баланса: body(объект) -> raw -> JSON.parse(data).
// remaining_credits может быть float (379.0) и лежать прямо в $json или в data-строке.
const r = $json;
const body = (r.body && typeof r.body === 'object') ? r.body : r;
const data = (body && typeof body.data === 'string') ? body.data : (typeof r.data === 'string' ? r.data : null);
let balance = null;
try {
  if (body.remaining_credits != null) balance = Number(body.remaining_credits);
  else if (r.remaining_credits != null) balance = Number(r.remaining_credits);
  else if (data) balance = Number(JSON.parse(data).remaining_credits);
} catch (e) {}
if (balance === null || !Number.isFinite(balance)) { return [{ json: { ok: false, error: 'balance_unavailable', raw: $json } }]; }
// asset_generator: 1 кред/шт, count 1..4 -> порог 5 покрывает любой count.
if (balance < 5) { return [{ json: { ok: false, error: 'low_credits', balance: balance } }]; }
return [{ json: { ...v, ok: true, balance: balance } }];

const r = $json;
const assets = Array.isArray(r.assets) ? r.assets : [];
const first = assets.length > 0 ? assets[0] : null;
return [{
  json: {
    ok: true,
    asset_id: r.id || null,
    url: (first && first.url) || null,
    status: r.status || null,
    credits_used: r.credits_used || 0,
    gen_type: r.gen_type || null,
    failed_reason: r.failed_reason || null,
    raw: r
  }
}];
